import json
from pathlib import Path
from collections import Counter, deque

task_json = Path("/home/USER/runs/paper/qwen-in-glm-hpl-u1/frozen/seen-5/play/users/u012/system/state/workspace/programs/task-026adbf3.json")

with open(task_json) as f:
    task_data = json.load(f)

def transform_demo1(inp):
    h, w = len(inp), len(inp[0])

    # Collect all dot positions
    dot_positions = set()
    for r in range(h):
        for c in range(w):
            if inp[r][c] == 2:
                dot_positions.add((r, c))

    # Find all cells connected to dots via 4s
    visited = set()
    reachable = set()
    queue = deque(dot_positions)

    while queue:
        r, c = queue.popleft()
        if (r, c) not in visited:
            visited.add((r, c))
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in visited:
                    if inp[nr][nc] == 4:
                        visited.add((nr, nc))
                        reachable.add((nr, nc))
                        queue.append((nr, nc))

    # Rebuild output
    out_rows = []
    for r in range(h):
        row = []
        for c in range(w):
            if inp[r][c] == 2:
                row.append(4)  # Dots become 4
            elif inp[r][c] == 4 and (r, c) in reachable:
                row.append(4)
            else:  # inp[r][c] == 4 and unreachable
                row.append(3)
        out_rows.append(row)

    return out_rows

print("=== TESTING ON DEMO 1 ===")
demo = task_data[1]
inp = demo['input']
out = demo['output']

test_out = transform_demo1(inp)
print(f"Predicted: {len(test_out)}x{len(test_out[0])}, Expected: {len(out)}x{len(out[0])}")

matches = all(test_out[r][c] == out[r][c] for r in range(len(out)) for c in range(len(out[0])))
print(f"Match: {matches}")

if not matches:
    mismatches = []
    for r in range(len(out)):
        for c in range(len(out[0])):
            if test_out[r][c] != out[r][c]:
                mismatches.append((r, c, test_out[r][c], out[r][c]))
    print(f"Mismatches: {len(mismatches)}")
    for r, c, pred, exp in mismatches[:5]:
        print(f"  [{r}][{c}]: pred={pred}, out={exp}")
